sys_variable_value.value:
(function() {
    gs.info("start");
    var gr = inputs.invoice_record;
    var fieldList = [];
    
    // Define the list of technical field names you want to audit
    var fieldNames = [
        'u_number', 
        'u_amount', 
        'u_tax_amount', 
        'u_invoice_due_date',
        'u_invoice_date'
    ];

    for (var i = 0; i < fieldNames.length; i++) {
        var fName = fieldNames[i];
        gs.info("for loop");
        // Check if field exists and has a value
        if (gr.isValidField(fName) && !gr.getElement(fName).nil()) {
            fieldList.push({
                "name": fName,
                "label": gr.getElement(fName).getLabel(),
                "value": gr.getDisplayValue(fName) // Gets formatted value (e.g., $1,200.00)
            });
            gs.info("yes this yes");
        }
    }

    // Set the output for the Action
    outputs.audit_list = fieldList;
})();

